alter table TIPIMODALITAPAGAMENTO add FLAG_DISABILITATO NUMERIC(1, 0);

ALTER TABLE RESPONSABILI ADD FK_OGGETTO_IMMAGINE numeric(10) ;

ALTER TABLE RESPONSABILI ADD CONSTRAINT FK_RESPONSABILI_OGGETTI FOREIGN KEY (IDCOMUNE , FK_OGGETTO_IMMAGINE )REFERENCES OGGETTI (  IDCOMUNE, CODICEOGGETTO);

